"""Compare guardian versions at filesystem/syscall boundaries; no real signals."""
import io
import json
import os
from pathlib import Path
import runpy
import signal
from types import SimpleNamespace
from unittest.mock import patch

HERE = Path(__file__).parent
ROOT, TARGET, PARENT, SIBLING, UID = 100, 101, 102, 103, 1000
NS = 'pid:[fixture]'

class Listing:
    def __init__(self, names): self.names = names
    def __enter__(self): return iter(SimpleNamespace(name=n, path='/proc/' + n) for n in self.names)
    def __exit__(self, *args): pass

def load(version):
    script = runpy.run_path(str(HERE / f'{version}.py'))
    script['stop'].__globals__.update(ROOT=ROOT, UID=UID, NAMESPACE=NS)
    return script

def run(version, case):
    script = load(version)
    ports = script['stop'].__globals__
    records = {ROOT: [ROOT, 'root', 1, 'S', UID, NS],
               TARGET: [TARGET, 'target', ROOT, 'S', UID, NS],
               SIBLING: [SIBLING, 'sibling', ROOT, 'S', UID, NS]}
    if case in ('stable-multihop', 'reaped-intermediate'):
        records[TARGET][2] = PARENT
        records[PARENT] = [PARENT, 'parent', SIBLING, 'S', UID, NS]
    target_row = tuple(records[TARGET])
    effects, reads = [], []
    denied = case == 'owned-sibling-unreadable'
    transitioned = False

    def open_stat(path, mode='r', buffering=-1, encoding=None, errors=None, newline=None):
        nonlocal transitioned
        pid = int(os.fspath(path).split('/')[2])
        reads.append(['open', pid])
        if case == 'reaped-intermediate' and pid == PARENT and not transitioned:
            transitioned = True
            records.pop(PARENT)
            records[TARGET][2] = ROOT
        if pid not in records:
            raise FileNotFoundError(2, 'No such file or directory', os.fspath(path))
        row = records[pid]
        fields = [row[3], str(row[2])] + ['0'] * 17 + [row[1]]
        payload = (f'{pid} (fixture) ' + ' '.join(fields)).encode()
        return io.TextIOWrapper(io.BytesIO(payload), encoding=encoding, errors=errors, newline=newline)

    def stat_directory(path, *args, **kwargs):
        pid = int(os.fspath(path).split('/')[2])
        reads.append(['owner', pid])
        if pid not in records:
            raise FileNotFoundError(2, 'No such file or directory', os.fspath(path))
        return SimpleNamespace(st_uid=records[pid][4])

    def namespace(path, *args, **kwargs):
        pid = int(os.fspath(path).split('/')[2])
        reads.append(['namespace', pid])
        if denied and pid == SIBLING:
            raise PermissionError(13, 'Permission denied', os.fspath(path))
        return records[pid][5]

    def names(): return [str(pid) for pid in (PARENT, TARGET, SIBLING, ROOT) if pid in records] + ['self', 'net', 'sys']
    def scan(path):
        assert os.fspath(path) == '/proc'
        reads.append(['enumerate', '/proc'])
        return Listing(names())
    def listing(path):
        assert os.fspath(path) == '/proc'
        reads.append(['enumerate', '/proc'])
        return names()

    def open_pidfd(pid):
        nonlocal denied
        if pid == TARGET and case.startswith('drain-'): denied = True
        return 987 if pid == TARGET else 988

    def send_pidfd(fd, sig):
        nonlocal denied
        effects.append([fd, int(sig)])
        if case.startswith('drain-'):
            records.pop(TARGET if fd == 987 else SIBLING, None)
            if fd == 987 and case == 'drain-transient-sibling-denial': denied = False

    with patch('builtins.open', open_stat), patch('io.open', open_stat), \
            patch('os.stat', stat_directory), patch('os.scandir', scan), patch('os.listdir', listing), \
            patch('os.readlink', namespace), patch('os.pidfd_open', side_effect=open_pidfd), \
            patch('os.close'), patch('signal.pidfd_send_signal', side_effect=send_pidfd), \
            patch('os.kill', side_effect=AssertionError('numeric PID signal')), \
            patch('os.waitpid', side_effect=ChildProcessError):
        try:
            if case.startswith('drain-'):
                ports['time'] = SimpleNamespace(monotonic=lambda: 0, sleep=lambda _seconds: None)
                script['drain'](SimpleNamespace(pid=TARGET))
            else:
                script['stop'](target_row, signal.SIGTERM)
            outcome = 'returned'
        except Exception as error:
            outcome = f'{type(error).__name__}: {error}'
    return {'version': version, 'case': case, 'outcome': outcome, 'signals': effects,
            'reads': reads, 'remainingMembers': sorted(set(records) - {ROOT})}

def identity_case(version, case):
    script = load(version)
    fields = ['S', str(ROOT)] + ['0'] * 17 + ['start']
    payload = (f'{TARGET} (fixture) ' + ' '.join(fields)).encode()
    if case == 'crlf': payload = payload.replace(b' ', b'\r\n')
    if case == 'bare-cr': payload = payload.replace(b' ', b'\r')
    if case == 'unicode-comm': payload = payload.replace(b'fixture', 'f\u00e9xture'.encode())
    if case == 'invalid-utf8': payload = payload.replace(b'fixture', b'fi\xffxture')
    if case == 'short-stat': payload = b'101 (fixture) S 100'
    if case == 'bad-parent': payload = payload.replace(b'S 100', b'S bad')
    reads = []
    def open_stat(path, mode='r', buffering=-1, encoding=None, errors=None, newline=None):
        reads.append(['open', os.fspath(path)])
        error = {'open-missing': FileNotFoundError, 'open-exited': ProcessLookupError,
                 'open-denied': PermissionError}.get(case)
        if error: raise error(13, 'fixture failure', os.fspath(path))
        return io.TextIOWrapper(io.BytesIO(payload), encoding=encoding, errors=errors, newline=newline)
    def owner(path, **kwargs):
        reads.append(['owner', os.fspath(path)])
        error = {'owner-missing': FileNotFoundError, 'owner-exited': ProcessLookupError,
                 'owner-denied': PermissionError}.get(case)
        if error: raise error(13, 'fixture failure', os.fspath(path))
        return SimpleNamespace(st_uid=UID + 1 if case == 'foreign-uid' else UID)
    def namespace(path):
        reads.append(['namespace', os.fspath(path)])
        error = {'namespace-missing': FileNotFoundError, 'namespace-exited': ProcessLookupError,
                 'namespace-denied': PermissionError}.get(case)
        if error: raise error(13, 'fixture failure', os.fspath(path))
        return NS
    with patch('builtins.open', open_stat), patch('io.open', open_stat), \
            patch('os.stat', owner), patch('os.readlink', namespace):
        try: outcome = script['identity'](TARGET)
        except Exception as error: outcome = f'{type(error).__name__}: {error}'
    return {'version': version, 'case': case, 'outcome': outcome, 'reads': reads}

for case in ('stable-direct', 'stable-multihop', 'owned-sibling-unreadable', 'reaped-intermediate',
             'drain-persistent-sibling-denial', 'drain-transient-sibling-denial'):
    for version in ('old', 'candidate'): print(json.dumps(run(version, case)), flush=True)
for case in ('valid', 'crlf', 'bare-cr', 'unicode-comm', 'invalid-utf8', 'short-stat', 'bad-parent',
             'open-missing', 'open-exited', 'open-denied', 'owner-missing', 'owner-exited', 'owner-denied',
             'namespace-missing', 'namespace-exited', 'namespace-denied', 'foreign-uid'):
    for version in ('old', 'candidate'): print(json.dumps(identity_case(version, case)), flush=True)

