"""Compare census failures, completion ordering and owned/unowned verification."""
import io
import json
import os
from pathlib import Path
import runpy
from types import SimpleNamespace
from unittest.mock import patch

HERE = Path(__file__).parent
ROOT, CHILD, OTHER, UID = 100, 101, 200, 1000
NS = 'pid:[fixture]'

def run(version, case):
    subject = runpy.run_path(str(HERE / (version + '.py')))
    subject['descendants'].__globals__.update(ROOT=ROOT, UID=UID, NAMESPACE=NS)
    events = []
    closed = False
    opens = {}
    class Listing:
        def __enter__(self):
            events.append('enter')
            if case == 'enter-denied': raise PermissionError(13, 'fixture denied', '/proc')
            return self
        def __iter__(self):
            for index, name in enumerate([str(CHILD), str(OTHER), 'self', 'sys', str(ROOT), 'name\udcff']):
                if case == 'iteration-denied' and index == 1:
                    raise PermissionError(13, 'fixture denied', '/proc')
                events.append(['entry', name])
                yield SimpleNamespace(name=name, path='/proc/' + name)
        def __exit__(self, *args):
            nonlocal closed
            closed = True
            events.append('exit')
            if case == 'exit-denied': raise PermissionError(13, 'fixture denied', '/proc')
    def scan(path):
        events.append(['scandir', os.fspath(path)])
        if case == 'scandir-denied': raise PermissionError(13, 'fixture denied', '/proc')
        return Listing()
    def opened(path, mode='r', buffering=-1, encoding=None, errors=None, newline=None):
        assert closed, 'metadata read before directory listing finished and closed'
        pid = int(os.fspath(path).split('/')[2]);events.append(['open', pid])
        opens[pid] = opens.get(pid, 0) + 1
        if case == 'owned-disappeared' and pid == CHILD and opens[pid] == 2:
            raise ProcessLookupError(3, 'fixture exited', os.fspath(path))
        start = 'reused' if case == 'owned-start-reused' and pid == CHILD and opens[pid] == 2 else 'original'
        ppid = ROOT if pid == CHILD else 1
        payload = (f'{pid} (fixture) ' + ' '.join(['S', str(ppid)] + ['0'] * 17 + [start])).encode()
        return io.TextIOWrapper(io.BytesIO(payload), encoding=encoding, errors=errors, newline=newline)
    def stat(path, **kwargs):
        pid = int(os.fspath(path).split('/')[2]);events.append(['owner', pid])
        return SimpleNamespace(st_uid=UID)
    def namespace(path):
        pid = int(os.fspath(path).split('/')[2]);events.append(['namespace', pid])
        if (case == 'owned-namespace-denied' and pid == CHILD) or (case == 'unrelated-namespace-denied' and pid == OTHER):
            raise PermissionError(13, 'fixture denied', os.fspath(path))
        return NS
    with patch('os.scandir', scan), patch('io.open', opened), patch('builtins.open', opened), \
            patch('os.stat', stat), patch('os.readlink', namespace):
        try: outcome = subject['descendants']()
        except Exception as error: outcome = f'{type(error).__name__}: {error}'
    return {'version': version, 'case': case, 'outcome': outcome, 'events': events}

for case in ('scandir-denied', 'enter-denied', 'iteration-denied', 'exit-denied', 'complete-before-open',
             'owned-namespace-denied', 'unrelated-namespace-denied', 'owned-start-reused', 'owned-disappeared'):
    for version in ('old', 'candidate'): print(json.dumps(run(version, case)), flush=True)

