"""[DEBUG-fnry17-identities] Exercise real parsers with synthetic syscall data."""
import hashlib
from contextlib import nullcontext
import json
import io
from pathlib import Path
import runpy
import signal
from types import SimpleNamespace
from unittest.mock import patch

OLD = Path('/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/mutation-clone/scripts/poc_browser_lifetime.py')
NEW = Path('/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/guardian-identity-only-candidate.py')
ROOT, ANCESTOR, TARGET, SIBLING, OUTSIDE = 100, 101, 102, 103, 201
UID, NS = 777, 'pid:[synthetic-owned]'

CASES = ['owned-sibling-unreadable', 'owned-sibling-reused-during-verification']

def row(pid, start, ppid, *, uid=UID, namespace=NS, comm='synthetic process'):
    return {'pid': pid, 'start': start, 'ppid': ppid, 'uid': uid,
            'namespace': namespace, 'comm': comm, 'state': 'S'}

def exercise(source, case, operation):
    loaded = runpy.run_path(str(source))
    ports = loaded['stop'].__globals__
    ports.update(ROOT=ROOT, UID=UID, NAMESPACE=NS)
    original_identity = ports['identity']
    records = {
        ROOT: row(ROOT, 'root-start', 0),
        ANCESTOR: row(ANCESTOR, 'ancestor-start', ROOT),
        TARGET: row(TARGET, 'target-start', ANCESTOR),
        SIBLING: row(SIBLING, 'sibling-start', ROOT),
        OUTSIDE: row(OUTSIDE, 'outside-start', 0),
    }
    if case == 'stable-direct':
        records[TARGET]['ppid'] = ROOT
    elif case.startswith('comm-'):
        prose = {'comm-spaces': 'many spaces in process name',
                 'comm-right-parentheses': '((right) parens)))',
                 'comm-newline': 'first line\nsecond line',
                 'comm-identity-looking-prose': 'S 100 Z 201 target-start ) 777'}[case]
        for record in records.values():
            record['comm'] = prose
    elif case == 'foreign-target-uid':
        records[TARGET]['uid'] += 1
    elif case == 'foreign-target-namespace':
        records[TARGET]['namespace'] = 'pid:[foreign]'
    elif case == 'foreign-ancestor-uid':
        records[ANCESTOR]['uid'] += 1
    elif case == 'foreign-ancestor-namespace':
        records[ANCESTOR]['namespace'] = 'pid:[foreign]'
    elif case == 'outside-family':
        records[TARGET]['ppid'] = OUTSIDE
    elif case == 'cyclic-ancestry':
        records[ANCESTOR]['ppid'] = TARGET
    elif case == 'missing-ancestry':
        del records[ANCESTOR]
    elif case == 'unrelated-denied-sibling':
        records[SIBLING]['ppid'] = OUTSIDE

    records.pop(ANCESTOR)
    records[TARGET]['ppid'] = ROOT
    reads, accesses, signalled = {}, [], []
    initial_scan_completed = False
    active = None

    def identity(pid, *, with_namespace=True):
        nonlocal active
        key = (pid, with_namespace)
        reads[key] = reads.get(key, 0) + 1
        active = (pid, with_namespace, reads[key])
        accesses.append({'pid': pid, 'namespace_requested': with_namespace, 'ordinal': reads[key]})
        return original_identity(pid, with_namespace=with_namespace)

    def current_record():
        pid, namespace, ordinal = active
        record = dict(records[pid]) if pid in records else None
        if record is None:
            raise FileNotFoundError('synthetic absent process')
        if case == 'vanished-target-after-open' and pid == TARGET and namespace:
            raise ProcessLookupError('synthetic target vanished')
        if case == 'vanished-target-during-lineage' and pid == TARGET and not namespace:
            raise ProcessLookupError('synthetic target vanished')
        if case == 'vanished-ancestor-before-lineage' and pid == ANCESTOR and not namespace:
            raise ProcessLookupError('synthetic ancestor vanished')
        if case == 'vanished-ancestor-during-verification' and pid == ANCESTOR and namespace:
            raise ProcessLookupError('synthetic ancestor vanished')
        if case == 'target-reused-start' and pid == TARGET:
            record['start'] = 'reused-target'
        if case == 'target-reused-during-verification' and pid == TARGET and namespace and ordinal >= 2:
            record['start'] = 'reused-target'
        if case == 'ancestor-reused-during-verification' and pid == ANCESTOR and namespace:
            record['start'] = 'reused-ancestor'
        if case == 'owned-sibling-reused-during-verification' and pid == SIBLING and namespace and initial_scan_completed:
            record['start'] = 'reused-sibling'
        return record

    def read_text(path, *args, **kwargs):
        record = current_record()
        assert str(path) == f'/proc/{record["pid"]}/stat'
        fields = [record['state'], str(record['ppid'])] + ['0'] * 17 + [record['start']]
        return f'{record["pid"]} ({record["comm"]}) ' + ' '.join(fields)

    def open_text(path, *args, **kwargs):
        assert not args and (not kwargs or kwargs == {'mode': 'r', 'encoding': io.text_encoding(None)})
        return io.StringIO(read_text(path))

    def stat(path, *args, **kwargs):
        record = current_record()
        assert str(path) == f'/proc/{record["pid"]}'
        return SimpleNamespace(st_uid=record['uid'])

    def namespace(path):
        record = current_record()
        assert str(path) == f'/proc/{record["pid"]}/ns/pid'
        denied = {'owned-target-unreadable': TARGET, 'owned-ancestor-unreadable': ANCESTOR,
                  'owned-sibling-unreadable': SIBLING, 'unrelated-denied-sibling': SIBLING}
        if denied.get(case) == record['pid'] and initial_scan_completed:
            raise PermissionError(13, 'synthetic namespace denial', str(path))
        return record['namespace']

    def pidfd_open(pid):
        assert pid in (TARGET, SIBLING)
        if case == 'vanished-before-pidfd':
            raise ProcessLookupError('synthetic target vanished before pidfd')
        return 12345 + pid

    def send(fd, sig):
        assert fd - 12345 in (TARGET, SIBLING)
        signalled.append({'pid': fd - 12345, 'signal': sig.name})

    original_scan = ports['descendants']
    def staged_scan():
        nonlocal initial_scan_completed
        members = original_scan()
        initial_scan_completed = True
        return members
    ports['descendants'] = staged_scan
    ports['identity'] = identity
    expected = (TARGET, 'target-start', records.get(TARGET, {}).get('ppid', ANCESTOR), 'S', UID, NS)
    outcome = {'case': case, 'operation': operation}
    with patch.object(Path, 'iterdir', lambda _self: iter(Path('/proc', str(pid)) for pid in records)), \
            patch.object(Path, 'read_text', read_text), patch.object(Path, 'stat', stat), \
            patch('builtins.open', open_text), patch('io.open', open_text), patch('os.stat', stat), \
            patch('os.listdir', lambda path: [str(pid) for pid in records]), \
            patch('os.scandir', lambda path: nullcontext([SimpleNamespace(name=str(pid)) for pid in records])), \
            patch('os.readlink', namespace), patch('os.pidfd_open', pidfd_open), \
            patch('os.close', lambda fd: None), patch('signal.pidfd_send_signal', send), \
            patch('os.kill', side_effect=AssertionError('unexpected PID-addressed signal')):
        try:
            if operation == 'staged-drain':
                with patch.dict(ports, {'reap': lambda child: None}):
                    loaded['drain'](None)
                outcome['outcome'] = 'completed-drain'
            elif operation == 'stop':
                loaded['stop'](expected, signal.SIGKILL)
                outcome['outcome'] = 'signalled' if signalled else 'accepted-noop'
            else:
                outcome['members'] = sorted(loaded['descendants']())
                outcome['outcome'] = 'accepted-scan'
        except (RuntimeError, PermissionError, ValueError, IndexError) as error:
            outcome['outcome'] = 'refused'
            outcome['error_type'] = type(error).__name__
            outcome['error'] = str(error)
    outcome['initial_scan_completed'] = initial_scan_completed
    outcome['signalled'] = signalled
    outcome['identity_accesses'] = accesses
    return outcome

results = []
for case in CASES:
    for operation in ('staged-drain',):
        before = exercise(OLD, case, operation)
        after = exercise(NEW, case, operation)
        semantic = lambda result: {key: result.get(key) for key in ('outcome', 'members', 'signalled', 'error_type')}
        results.append({'case': case, 'operation': operation, 'old': before, 'new': after,
                        'different': semantic(before) != semantic(after)})

print(json.dumps({'tag': 'DEBUG-fnry17-identities', 'command': 'python3 identity_only_staged_identity_differential.py',
                  'fixture_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                  'sources': {str(path): hashlib.sha256(path.read_bytes()).hexdigest() for path in (OLD, NEW)},
                  'cases': len(CASES), 'operation_pairs': len(results), 'results': results}, indent=2))

